            for (RefundLine l : part) l.submitted(batchId);
            batchIds.add(batchId);
            completed += RefundResultMatcher.apply(part, pg.status(batchId));
        }
        int awaiting = (int) pending.stream().filter(l -> l.status() == RefundLine.Status.SUBMITTED).count();
        return new RunResult(runId, List.copyOf(batchIds), pending.size(), completed, awaiting);
    }

    /** A line queued twice by a CS double-click must be refunded once. */
    private List<RefundLine> uniquePending() {
        Map<String, RefundLine> byKey = new LinkedHashMap<>();
        for (RefundLine l : refunds.pending()) {
            byKey.putIfAbsent(l.orderNo() + "#" + l.lineNo(), l);
        }
        return new ArrayList<>(byKey.values());
    }
}
package infra;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

/** Thin wrapper around the PG vendor CLI (vendor/bin/pgsim). One process per call. */
public class PgsimClient {
    /** What the PG reports for one payment. */
    public record Txn(String tid, long amount, long refunded, long balance) {}

    /** One row of a PG batch status: refund number, TID, amount, merchant field. */
    public record RefundRow(String refundNo, String tid, long amount, String aux) {}

    private final Path bin;
    private final Path home;
    private final long timeoutSeconds;

    public PgsimClient(Path bin, Path home, long timeoutSeconds) {
        this.bin = bin;
        this.home = home;
        this.timeoutSeconds = timeoutSeconds;
    }

    /** Charges the customer; returns the PG transaction id. */
    public String pay(String mid, long amount, String orderNo) {
        return run(List.of("pay", "--mid", mid, "--amt", Long.toString(amount), "--oid", orderNo)).strip();
    }

    /** Submits one refund batch file; returns the accepted count reported by the PG. */
    public int refund(String mid, String batchId, Path file) {
        String out = run(List.of("refund", "--mid", mid, "--batch", batchId, file.toString())).strip();
        String[] t = out.split("\\s+");
        if (t.length != 2 || !t[0].equals("accepted")) {
            throw new PgException("unexpected refund reply: " + out);
        }
        return Integer.parseInt(t[1]);
    }

    public List<RefundRow> status(String batchId) {
        List<RefundRow> rows = new ArrayList<>();
        for (String line : run(List.of("status", "--batch", batchId)).split("\n")) {
            if (line.isBlank()) continue;
            String[] f = line.split("\t");
            if (f.length != 4) throw new PgException("unexpected status line: " + line);
            rows.add(new RefundRow(f[0], f[1], Long.parseLong(f[2]), f[3].equals("-") ? "" : f[3]));
        }
        return rows;
    }

    public Txn txn(String tid) {
        Map<String, String> kv = new HashMap<>();
        for (String line : run(List.of("txn", tid)).split("\n")) {
            int sp = line.indexOf(' ');
            if (sp > 0) kv.put(line.substring(0, sp), line.substring(sp + 1).strip());
        }
        return new Txn(kv.get("tid"), Long.parseLong(kv.get("amt")), Long.parseLong(kv.get("refunded")),
                Long.parseLong(kv.get("bal")));
    }

    private String run(List<String> args) {
        List<String> cmd = new ArrayList<>();
        cmd.add(bin.toString());
        cmd.addAll(args);
        try {
            Files.createDirectories(home);
            ProcessBuilder pb = new ProcessBuilder(cmd);
            pb.environment().put("PGSIM_HOME", home.toAbsolutePath().toString());
            Process p = pb.start();
            byte[] out;
            byte[] err;
            try (InputStream o = p.getInputStream(); InputStream e = p.getErrorStream()) {
                out = o.readAllBytes();
                err = e.readAllBytes();
            }
            if (!p.waitFor(timeoutSeconds, TimeUnit.SECONDS)) {
                p.destroyForcibly();
                throw new PgException("timeout: " + String.join(" ", cmd));
            }
            if (p.exitValue() != 0) {
                throw new PgException("pgsim failed [" + new String(err, StandardCharsets.UTF_8).strip() + "]: "
                        + String.join(" ", cmd));
            }
            return new String(out, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new PgException("exec failed: " + e.getMessage());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new PgException("interrupted");
        }
    }

    public static class PgException extends RuntimeException {
        public PgException(String msg) {
            super(msg);
        }
    }
}
package service;

import domain.RefundLine;
import infra.PgsimClient.RefundRow;
import infra.RefundFileWriter;

import java.util.ArrayList;
import java.util.List;

/** Attaches PG refund numbers from a batch status to the lines we sent in that batch. */
public final class RefundResultMatcher {
    private RefundResultMatcher() {}

    /** Returns how many lines got a refund number. Each PG row is used at most once. */
    public static int apply(List<RefundLine> sent, List<RefundRow> rows) {
        List<RefundRow> free = new ArrayList<>(rows);
        int matched = 0;
        for (RefundLine line : sent) {
            String ref = RefundFileWriter.merchantRef(line);
            for (int i = 0; i < free.size(); i++) {
                RefundRow row = free.get(i);
                if (row.tid().equals(line.tid()) && row.amount() == line.amount() && row.aux().equals(ref)) {
                    line.done(row.refundNo());
                    free.remove(i);
                    matched++;
                    break;
                }
            }
        }
        return matched;
    }
}
package domain;

import java.time.LocalDate;

/** Refund of one order line. Mutable status, owned by the refund repository. */
public final class RefundLine {
    public enum Status {
        /** accepted by CS, waiting for the nightly refund run */
        REQUESTED,
        /** sent to the PG in a refund batch, no PG refund number yet */
        SUBMITTED,
        /** PG refund number received */
        DONE
    }

    private final String requestId;
    private final String orderNo;
    private final int lineNo;
    private final String tid;
    private final long amount;
    private final LocalDate requestedOn;
    private Status status = Status.REQUESTED;
    private String batchId;
    private String refundNo;

    public RefundLine(String requestId, String orderNo, int lineNo, String tid, long amount, LocalDate requestedOn) {
        this.requestId = requestId;
        this.orderNo = orderNo;
        this.lineNo = lineNo;
        this.tid = tid;
        this.amount = amount;
        this.requestedOn = requestedOn;
    }

    public String requestId() { return requestId; }
    public String orderNo() { return orderNo; }
    public int lineNo() { return lineNo; }
    public String tid() { return tid; }
    public long amount() { return amount; }
    public LocalDate requestedOn() { return requestedOn; }
    public Status status() { return status; }
    public String batchId() { return batchId; }
    public String refundNo() { return refundNo; }

    public void submitted(String batchId) {
        this.status = Status.SUBMITTED;
        this.batchId = batchId;
    }

    public void done(String refundNo) {
        this.status = Status.DONE;
        this.refundNo = refundNo;
    }

    @Override
    public String toString() {
        return requestId + "/" + orderNo + "#" + lineNo + " " + amount + " " + status;
    }
}

